 android.view.View projectIcon(String name){String key=name.toLowerCase(java.util.Locale.ROOT);String resource=key.contains("camarad")?"camarad_original":key.contains("hvost")?"hvost_original":key.equals("screen-recorder-downloads")?"recorder_original":key.equals("fragment-logo-editor")?"fragment_original":key.startsWith("enduro")?"enduro_original":"icon";ImageView icon=new ImageView(this);icon.setImageDrawable(getDrawable(getResources().getIdentifier(resource,"drawable",getPackageName())));icon.setScaleType(ImageView.ScaleType.FIT_CENTER);icon.setContentDescription("Логотип "+ProjectThreads.title(name));return icon;}
 SecretKey key()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias("github")){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("github",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return (SecretKey)ks.getKey("github",null);}
 void saveToken(String token)throws Exception{if(token.isEmpty()){prefs().edit().remove("secret").remove("iv").apply();return;}Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());prefs().edit().putString("secret",android.util.Base64.encodeToString(c.doFinal(token.getBytes("UTF-8")),2)).putString("iv",android.util.Base64.encodeToString(c.getIV(),2)).apply();}
