 void updateMessage(String text){if(!isFinishing()&&!isDestroyed()){status.setText(text);if(foreground)Toast.makeText(this,text,Toast.LENGTH_LONG).show();}}
 UpdateEngine.Release releaseModel(JSONObject r){JSONArray values=r.optJSONArray("abis");if(values==null)values=r.optJSONArray("abi");java.util.Set<String> abis=new java.util.HashSet<>();if(values!=null)for(int i=0;i<values.length();i++)abis.add(values.optString(i));return new UpdateEngine.Release(r.optInt("versionCode",-1),r.optString("versionName"),r.optString("channel"),r.optString("apkUrl"),r.optString("sha256"),r.optLong("sizeBytes",-1),r.optInt("minSdk",26),r.optInt("maxSdk",0),abis,r.optBoolean("withdrawn"));}
