 int signingFlags(){return Build.VERSION.SDK_INT>=28?android.content.pm.PackageManager.GET_SIGNING_CERTIFICATES:android.content.pm.PackageManager.GET_SIGNATURES;}
 UpdateEngine.Identity installedIdentity()throws Exception{return identity(getPackageManager().getPackageInfo(getPackageName(),signingFlags()),null);}
